"""A SQL concatenation that LOOKS injectable but is not reachable.

The trap: run_query() builds SQL by concatenation, which is what a scanner or a
single-pass reader flags. But two validation layers sit between the HTTP entry
point and that call, and both reject the metacharacters any injection needs.

Checkpoint 2.2 exists for exactly this shape. A reader that skims the layers
marks them "passes" and produces a false positive; one agent per layer, each
required to quote the code, does not.
"""

import re

ALLOWED_TERM = re.compile(r"\A[A-Za-z0-9 _-]{1,64}\Z")


def handle_search(request_args: dict[str, str]) -> list[tuple]:
    """Entry point. Layer 1."""
    term = request_args.get("q", "")
    if not ALLOWED_TERM.match(term):
        raise ValueError("search term contains unsupported characters")
    return _dispatch_search(term)


def _dispatch_search(term: str) -> list[tuple]:
    """Layer 2. Belt and braces: reject anything that survived layer 1."""
    if any(ch in term for ch in "'\";\\--"):
        raise ValueError("rejected metacharacter")
    return run_query(term)


def run_query(term: str) -> list[tuple]:
    """The apparent sink. Reachable only with [A-Za-z0-9 _-] input."""
    sql = "SELECT id, title FROM documents WHERE title LIKE '%" + term + "%'"
    return _execute(sql)


def _execute(sql: str) -> list[tuple]:
    raise NotImplementedError("wired to a real cursor in the app")

