export const meta = {
  name: 'verify-attack-path',
  description:
    'Checkpoints 2.2-2.5 and 3.1-3.3: verify each validation layer independently, check recovery, align to the threat model, then verify impact',
  whenToUse:
    'After checkpoint 2.1 has identified the entry point and enumerated the validation layers between it and the vulnerable sink. Gates PoC development.',
  phases: [
    { title: 'Layers' },
    { title: 'Impact' },
  ],
}

// args: { baseDir, finding, entryPoint, layers[], scope }
//
// Checkpoint 2.2's pass criteria are "identified every layer, determined
// pass/block/uncertain for each with evidence, ZERO uncertain layers". That is
// a fan-out over an enumerated list, which one agent reading in a single pass
// cannot honestly satisfy. One agent per layer makes each verdict independent
// and makes the zero-uncertain criterion checkable rather than aspirational.

const { baseDir, finding, entryPoint, layers = [], scope } = args

const MAX_LAYERS = 4

const LAYER_SCHEMA = {
  type: 'object',
  required: ['verdict', 'evidence'],
  properties: {
    verdict: { enum: ['PASSES', 'BLOCKS', 'UNCERTAIN'] },
    location: { type: 'string', description: 'file:line of the check itself' },
    evidence: { type: 'string', description: 'the code, and why the payload survives or does not' },
    reason: { type: 'string' },
  },
}

const RECOVERY_SCHEMA = {
  type: 'object',
  required: ['recoveryExists', 'effectiveImpact', 'evidence'],
  properties: {
    recoveryExists: { type: 'boolean' },
    mechanism: { type: 'string', description: 'e.g. net/http per-connection recover in conn.serve' },
    effectiveImpact: { type: 'string', description: 'the impact that survives recovery' },
    evidence: { type: 'string' },
  },
}

const THREAT_SCHEMA = {
  type: 'object',
  required: ['inScope', 'byDesign', 'byDesignIndicators', 'evidence'],
  properties: {
    inScope: { enum: ['YES', 'NO', 'UNCERTAIN'] },
    byDesign: { type: 'boolean' },
    byDesignIndicators: { type: 'integer', description: 'count of the three indicator classes that fired' },
    evidence: { type: 'string' },
  },
}

const IMPACT_SCHEMA = {
  type: 'object',
  required: ['result', 'impact', 'rootCause', 'classification', 'evidence'],
  properties: {
    result: { enum: ['VERIFIED', 'NOT_VERIFIED', 'DISPROVEN'] },
    impact: { type: 'string' },
    rootCause: { enum: ['internal', 'integration', 'external'] },
    externalPrecondition: { type: 'string' },
    classification: { enum: ['vulnerability', 'hardening_gap'] },
    evidence: { type: 'string' },
  },
}

// Pure. Reject an arg shape this script does not understand, BEFORE spending
// agents on it.
//
// Found by the first live run: the orchestrator sent finding.title,
// finding.initialImpactClaim, entryPoint.function and entryPoint.exampleInput,
// and passed `scope` as an object. The prompts interpolate finding.summary,
// finding.claimedImpact, entryPoint.description, entryPoint.payload and a
// string scope, so the threat-model agent was asked about "Finding: undefined,
// Component: undefined, Declared scope: [object Object]" and spent a full agent
// reasoning about nothing. Interpolating undefined must be a hard stop, not a
// silent degradation.
function missingArgs(a) {
  const missing = []
  const need = (path, value) => {
    if (value === undefined || value === null || value === '') missing.push(path)
  }
  const finding = (a && a.finding) || {}
  const entry = (a && a.entryPoint) || {}

  need('baseDir', a && a.baseDir)
  need('finding.summary', finding.summary)
  need('finding.sink', finding.sink)
  need('finding.component', finding.component)
  need('finding.claimedImpact', finding.claimedImpact)
  need('entryPoint.description', entry.description)
  need('entryPoint.location', entry.location)
  need('entryPoint.payload', entry.payload)

  if (a && a.scope !== undefined && a.scope !== null && typeof a.scope !== 'string') {
    missing.push('scope (must be a string; an object interpolates as [object Object])')
  }
  for (const [i, layer] of ((a && a.layers) || []).entries()) {
    if (!layer || !layer.name) missing.push(`layers[${i}].name`)
    if (!layer || !layer.location) missing.push(`layers[${i}].location`)
  }
  return missing
}

const argProblems = missingArgs(args)
if (argProblems.length > 0) {
  log(`BLOCKED: dispatch contract violated — ${argProblems.join(', ')}`)
  return {
    status: 'BLOCKED',
    reason: `verify-attack-path received an unusable arg shape: ${argProblems.join(', ')}. See the Dispatch section of SKILL.md for the required fields.`,
  }
}

// ---------------------------------------------------------------- Phase 2 + 3

phase('Layers')

const selected = layers.slice(0, MAX_LAYERS)
if (layers.length > selected.length) {
  const skipped = layers.slice(MAX_LAYERS).map((l) => l.name || l.location).join(', ')
  log(`Capped at ${MAX_LAYERS} layers. NOT verified: ${skipped}. Treat as UNCERTAIN.`)
}

const checks = [
  ...selected.map((layer, i) => () =>
    agent(
      `You are verifying ONE validation layer, independently. Do not reason about the others.

Finding: ${finding.summary}
Entry point: ${entryPoint.description} (${entryPoint.location})
Attacker payload: ${entryPoint.payload}

Layer under test: ${layer.name} at ${layer.location}
What it checks: ${layer.checks || 'determine this from the code'}

Read the actual code. Decide whether the payload above survives this layer and
reaches the next hop toward ${finding.sink}. Quote the code in your evidence.

Answer UNCERTAIN if you cannot establish it from the code. UNCERTAIN is a
legitimate answer and is preferable to a guess; it halts the pipeline for a
manual trace, which is the intended behaviour.`,
      { label: `layer:${layer.name || i + 1}`, phase: 'Layers', schema: LAYER_SCHEMA, effort: 'low' },
    ).then((v) => ({ layer: layer.name || `layer-${i + 1}`, location: layer.location, ...v })),
  ),

  () =>
    agent(
      `Checkpoint 2.3, recovery mechanism check.

Read ${baseDir}/references/RECOVERY_MECHANISMS.md, in particular the summary
table and the checklist before claiming a process crash.

Finding: ${finding.summary}
Claimed impact: ${finding.claimedImpact}
Vulnerable code: ${finding.sink}

Determine whether a panic/exception at that location is caught by any recovery
in the call stack — language-level, framework middleware, or server built-in —
and state the impact that actually survives.

Do not assume recovery is absent because you did not find it. If the claimed
impact is a process crash, that claim requires positive evidence that nothing
recovers.`,
      { label: 'recovery', phase: 'Layers', schema: RECOVERY_SCHEMA, effort: 'medium' },
    ),

  () =>
    agent(
      `Checkpoints 3.1, 3.2 and 3.3: threat model alignment.

Read ${baseDir}/references/VALIDATION_DIMENSIONS.md.

Finding: ${finding.summary}
Component: ${finding.component}
Declared scope: ${scope || 'none declared — report UNCERTAIN rather than assuming'}

Answer three things:
  3.1 Is this component explicitly in scope? Ambiguous means UNCERTAIN, not YES.
  3.2 Does this violate a security property the target claims, or is it within
      stated trust assumptions?
  3.3 Design intent. Check all three indicator classes: privilege identifiers,
      symmetric guarded/unguarded sibling paths, and documentation or tests
      covering it as normal operation. Report how many fired. If two or more
      fire, search usage and test coverage before concluding.

Centralized control is not by itself a vulnerability.`,
      { label: 'threat-model', phase: 'Layers', schema: THREAT_SCHEMA, effort: 'medium' },
    ),
]

// A dead agent yields null rather than throwing, so filter before use.
const results = (await parallel(checks)).filter(Boolean)

// The barrier is justified: the gate below is a decision over ALL layers, and a
// blocking layer skips the build and review workflows entirely.

const layerVerdicts = results.filter((r) => r.verdict)
const recovery = results.find((r) => typeof r.recoveryExists === 'boolean')
const threat = results.find((r) => r.inScope)

// Checkpoint 2.2's gate, as a pure function so it can be tested without a model.
//
// attemptedLayers is how many layer agents were dispatched; uncheckedLayers is
// how many were dropped by the cap. Both matter: a verdict list shorter than
// attemptedLayers means agents died, and a gate that inspected nothing must not
// report PROCEED.
function decideGate(verdicts, threatVerdict, attemptedLayers, uncheckedLayers) {
  const where = (ls) => ls.map((l) => `${l.layer} (${l.location})`).join(', ')

  const missing = attemptedLayers - verdicts.length
  if (missing > 0) {
    return {
      status: 'BLOCKED',
      reason: `${missing} layer agent(s) returned nothing; checkpoint 2.2 is unverified`,
    }
  }

  const blocked = verdicts.filter((l) => l.verdict === 'BLOCKS')
  if (blocked.length > 0) {
    return { status: 'NOT_EXPLOITABLE', reason: `blocked at ${where(blocked)}` }
  }

  const uncertain = verdicts.filter((l) => l.verdict === 'UNCERTAIN')
  if (uncertain.length > 0 || uncheckedLayers > 0) {
    const reason = [
      uncertain.length ? `unresolved layers: ${where(uncertain)}` : null,
      uncheckedLayers > 0 ? `${uncheckedLayers} layer(s) never inspected (cap)` : null,
    ]
      .filter(Boolean)
      .join('; ')
    return { status: 'BLOCKED', reason }
  }

  if (!threatVerdict) {
    return { status: 'BLOCKED', reason: 'threat-model agent returned nothing; checkpoints 3.1-3.3 unverified' }
  }
  if (threatVerdict.inScope === 'NO') {
    return { status: 'OUT_OF_SCOPE', reason: threatVerdict.evidence }
  }
  if (threatVerdict.inScope === 'UNCERTAIN') {
    return { status: 'BLOCKED', reason: 'scope ambiguous; checkpoint 3.1 requires clarification' }
  }
  if (threatVerdict.byDesign) {
    return { status: 'NOT_VULNERABLE', reason: threatVerdict.evidence }
  }

  return { status: 'PROCEED', reason: '' }
}

const gate = decideGate(layerVerdicts, threat, selected.length, layers.length - selected.length)

if (gate.status !== 'PROCEED') {
  log(`${gate.status}: ${gate.reason}`)
  return { status: gate.status, reason: gate.reason, layers: layerVerdicts, recovery, threat }
}

// ------------------------------------------------------- Checkpoints 2.4-2.5

phase('Impact')

const impact = await agent(
  `Checkpoints 2.4, 2.4b and 2.5.

Finding: ${finding.summary}
Originally claimed impact: ${finding.claimedImpact}
Recovery finding: ${recovery ? `${recovery.recoveryExists ? 'recovery EXISTS' : 'no recovery found'} — ${recovery.effectiveImpact}` : 'not established'}
All ${layerVerdicts.length} validation layers were independently verified as passable.

2.4  Verify the claimed impact against evidence. If recovery downgrades it, the
     verified impact is the downgraded one, not the original claim.
2.4b Attribute the root cause: internal, integration, or external. If it is not
     internal, state the external precondition the attack requires.
2.5  Classify: does the code DO something it should not (vulnerability), or LACK
     something it should have (hardening gap)?

See ${baseDir}/references/CHECKPOINTS.md for the pass criteria of each.`,
  { label: 'impact', phase: 'Impact', schema: IMPACT_SCHEMA, effort: 'high' },
)

if (!impact || impact.result === 'DISPROVEN') {
  log('NOT_EXPLOITABLE: impact disproven at checkpoint 2.4.')
  return { status: 'NOT_EXPLOITABLE', reason: impact ? impact.evidence : 'impact agent failed', layers: layerVerdicts, recovery, threat, impact }
}

log(`PROCEED to PoC development. Verified impact: ${impact.impact} (${impact.classification}, ${impact.rootCause} root cause)`)

return { status: 'PROCEED', layers: layerVerdicts, recovery, threat, impact }

